        unseen("LEVEL_OF[players[6].difficulty]", LEVEL_OF[players[6].difficulty])
      end
    elseif LEVEL_OF[players[6].difficulty] == 2 then
    else
      unseen("LEVEL_OF[players[6].difficulty]", LEVEL_OF[players[6].difficulty])
    end
    game.set_daylight_everywhere(({ [0] = 1, [1] = 0 })[(game.uses_day_night() and 1 or 0)] ~= 0)
    if (game.uses_morale() and 1 or 0) == 0 then
      game.morale_steady("Good")
    elseif (game.uses_morale() and 1 or 0) == 1 then
      game.free_morale()
    else
      unseen("(game.uses_morale() and 1 or 0)", (game.uses_morale() and 1 or 0))
    end
  end

  -- The win.
  local t0 = trigger.count{type = "IonDriveModule", compare = ">=", count = 1}
  mission.victory(t0, "Launch the Ion Drive Module.")
  local t2 = trigger.count{type = "FusionDriveModule", compare = ">=", count = 1}
  mission.victory(t2, "Launch the Fusion Drive Module.")
  local t4 = trigger.count{type = "CommandModule", compare = ">=", count = 1}
  mission.victory(t4, "Launch the Command Module.")
  local t6 = trigger.count{type = "FuelingSystems", compare = ">=", count = 1}
  mission.victory(t6, "Launch the Fueling Systems.")
  local t8 = trigger.count{type = "HabitatRing", compare = ">=", count = 1}
  mission.victory(t8, "Launch the Habitat Ring.")
  local t10 = trigger.count{type = "SensorPackage", compare = ">=", count = 1}
  mission.victory(t10, "Launch the Sensor Package.")
  local t12 = trigger.count{type = "Skydock", compare = ">=", count = 1}
  mission.victory(t12, "Launch the Skydock.")
  local t14 = trigger.count{type = "StasisSystems", compare = ">=", count = 1}
  mission.victory(t14, "Launch the Stasis Systems.")
  local t16 = trigger.count{type = "OrbitalPackage", compare = ">=", count = 1}
  mission.victory(t16, "Launch the Orbital Package.")
  local t18 = trigger.count{type = "PhoenixModule", compare = ">=", count = 1}
  mission.victory(t18, "Launch the Phoenix Module.")
  if game.disasters_enabled() then
    trigger.time{min = 18000, max = 22000, one_shot = false, on = Meteor}  -- after 180 to 220 marks
    trigger.time{min = 12000, max = 18000, one_shot = false, on = Vortex}  -- after 120 to 180 marks
  end
  return true
end
